import math

def C(N):
    if N <= 0:
        return 0
    # Candidate formula derived for N=2^k: C(N) = N^2 - 2N + N * log2(N)
    return N*N - 2*N + N * math.log2(N)

print(f"C(2) = {C(2)}")
print(f"C(4) = {C(4)}")
